sys_script_client.script:
function onLoad() {

    var eventId = g_form.getUniqueValue();

    if (eventId) {
        var ga = new GlideAjax('EventUtilsClient');
        ga.addParam('sysparm_name', 'getEventDetails');
        ga.addParam('sysparm_eventId', eventId);

        ga.getXMLAnswer(function(response) {
            var eventDetails = JSON.parse(response);
            if (eventDetails.name) {
				g_form.addInfoMessage('Event Name: '+eventDetails.name+' Event Date: '+eventDetails.date+' Location: '+eventDetails.location+' Status: '+eventDetails.status);
            }
			if (eventDetails.vip == true) {
				g_form.addInfoMessage('This is a VIP event!');
			}
        });
    }
}
